"""Aggregate measured cohort/ten-worker results without starting any simulation."""
import sys,json,hashlib,statistics
from pathlib import Path

def load(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main(root):
    root=Path(root).resolve();cohort=load(root/'ten_cohort_generation.json');parallel=load(root/'phase3_ten_parallel/report.json');proxy=load(root/'proxy_coverage.json');mesh=load(root/'mesh_reconcile_final.json');before=load(root/'protected_source_before.json')
    samples=load(root/'phase3_ten_parallel/resource_samples.json');latencies=[x for r in parallel['rounds'] for x in r['dispatch_to_collection_seconds']];integration_times=[sum(s['seconds'] for s in item['info']['acceptance_observed']['substeps']) for q in parallel['rounds'] for item in q['results']]
    assets=[]
    for seed in (101,202,303,404,505,606,707,808,909,1010,1101,1202):
        item=cohort['assets'].get(str(seed));assets.append({'seed':seed,'split':'eval' if seed in (1101,1202) else 'train','status':'STAGE_A_PASS_AND_REAL_PARALLEL_TEST_PASS' if item and item.get('independent_stage_a')=='PASS' and parallel['status']=='PASS' else 'NOT_GENERATED','directory':None if item is None else item['directory'],'stl_sha256':None if item is None else item.get('stl_sha256'),'stage_a_report':None if item is None else item.get('stage_a_report')})
    cpu=[x for r in parallel['rounds'] for x in r['cpu_percent_one_core_100']];rate=parallel['aggregate_rl_steps_per_second']
    r={'overall_status':'NOT_READY_FOR_FORMAL_TRAINING','latest_user_sequence':'Generate ten training assets completely, then ten simultaneous production SOFA environments. No individual post-generation SOFA test after user changed sequence.','phase1':{'status':'NOT_VERIFIED','mesh_position_scaling_connectivity':mesh['status'],'proxy_radius_configuration':proxy['radius_configuration_match'],'no_missed_whole_entity_penetration_due_to_proxies':'NOT_VERIFIED','source_reason':'LocalMinDistance ignores Triangle-Line. Sparse Point coverage and active Line-Line wall feature coverage are not a certified whole-body collision proof. Failed sufficient bound is not observed penetration.','self_intersection_certificate':'NOT_VERIFIED'},'phase2':{'status':'PASS_FOR_TEN_COHORT_GEOMETRY_AND_INITIAL_MOTION','fixed_recipe':'TypeI / diameter0.85 / voxel0.3mm / clean0.001mm / simplify_error0.01mm / decimate0.25','generator_source_profile_frozen':True,'all_ten_independent_stage_a':'PASS','all_ten_reset_and_41d_state':'PASS','earlier_seed202_test_before_sequence_change':{'steps':2,'actual_substeps':44}},'phase3':{'status':parallel['status'],'worker_pids':parallel['worker_pids'],'actual_observed_physics_substeps':parallel['actual_observed_physics_substeps'],'rl_steps':90,'substeps_per_rl_step':22,'dt_s':.006,'replay_batch_shape':parallel['replay_sample_shape'],'reset_and_history_continuity':parallel['history_reset_and_continuity'],'worker_exit_codes':parallel['worker_exit_codes'],'all_ten_active_resource_intervals':sum(q['intervals_all_ten_cpu_active'] for q in parallel['rounds'])},'performance':{'aggregate_rl_steps_per_second':rate,'ten_environment_round_seconds':[q['wall_seconds'] for q in parallel['rounds']],'mean_dispatch_to_collection_seconds':statistics.mean(latencies),'max_dispatch_to_collection_seconds':max(latencies),'mean_observed_physics_seconds_per_env_action':statistics.mean(integration_times),'mean_cpu_percent_per_worker_one_core_100':statistics.mean(cpu),'peak_simultaneous_worker_rss_gib':max(sum(w['rss_mib'] for w in s['workers']) for s in samples)/1024,'peak_rss_mib_per_worker':[max(q['peak_rss_mib'][i] for q in parallel['rounds']) for i in range(10)],'seconds_including_resets':parallel['seconds_including_resets'],'instrumentation_overhead_included':True,'heatup_500k_steps_sampling_only_days':500000/rate/86400,'configured_20m_steps_sampling_only_days':20000000/rate/86400,'projection_warning':'Short zero-action sampling rate only, not a reliable training ETA; optimizer and full navigation/contact may reduce throughput.'},'phase4':{'status':'TEN_TRAINING_ASSETS_PREPARED_NOT_PRODUCTION_RELEASED','eval1101_1202':'NOT_GENERATED_PENDING_FIRST_PHASE_ACCEPTANCE','default_cache_publication':'NOT_DONE','reason':'Unverified mandatory whole-body collision coverage was not relabeled PASS to release the original12-vessel production batch.'},'assets':assets,'preflight':{'configuration':'PASS','command':'PYTHONPATH="$PWD/python:${PYTHONPATH:-}" python -B -m mcr_sim.train --preflight','default_cache_inventory':load(root/'default_asset_inventory.json'),'warning':'Production --preflight prints config, not asset-loading validation.'},'production_source_preservation':{'status':'PASS' if all(Path(p).is_file() and sha(Path(p))==h for p,h in before.items()) else 'FAIL','files':len(before)},'training_started':False,'optimizer_steps':0,'remaining_risks':['Full catheter proxy/wall response coverage still NOT_VERIFIED.','Robust global STL self-intersection certification remains NOT_VERIFIED.','Ten-way short tests did not load the wall or demonstrate full navigation success.','Two evaluation assets and default-cache publication are not released; training/eval seed sets remain disjoint.','SAC forward, backward, checkpoint resume and learning behavior were not exercised.'],'test_source_sha256':{str(p):sha(p) for p in (root.parents[1]/'test_scripts').glob('pretrain_*.py')}}
    (root/'FINAL_REPORT.json').write_text(json.dumps(r,indent=2)+'\n')
    lines=['# Pre-training environment acceptance: ten training vessels / ten real SOFA processes','','Latest requested ten-vessel generation and ten-way execution: completed. Formal training readiness: NOT_READY.','','## Actual results','','- Ten TypeI/0.85/0.3mm training assets generated with one frozen recipe; all generator validation and independent Stage A passed.','- Ten real SOFA21.12 workers completed90 RL actions /1980 observed physical integrations, exactly22 per action and dt0.006s.','- Finite41D observations, environment IDs, reset isolation and8-frame replay truncation passed. Replay sample shape32x8x41. All ten worker exits0.','- Resetting environment0 consumed0 CPU seconds in each other worker; their insertion, episode clock and replay histories remained continuous.','- No SAC networks, optimizer or training started.','','## Performance','','Aggregate RL steps/s: %.6f. Mean dispatch-to-collection latency: %.3fs. Maximum: %.3fs.'%(rate,statistics.mean(latencies),max(latencies)),'Mean observed physical-integration seconds per environment action: %.3f.'%statistics.mean(integration_times),'Mean per-worker CPU: %.2f%%, where100%% is one core. Peak simultaneous worker RSS: %.3fGiB.'%(statistics.mean(cpu),r['performance']['peak_simultaneous_worker_rss_gib']),'Total ten-environment test including startup/resets: %.3fs.'%parallel['seconds_including_resets'],'Sampling-only arithmetic projection:500k warmup steps ~%.1f days;20M steps ~%.1f days. Not an actual ETA.'%(r['performance']['heatup_500k_steps_sampling_only_days'],r['performance']['configured_20m_steps_sampling_only_days']),'','## Mandatory unresolved gate','','Source-backed runtime mesh scaling and oriented topology match. The prior bitwise-equality test failure was floating arithmetic, not a misplaced mesh; its original report is preserved. Both catheter collision proximities match0.665mm outer radius.','','However LocalMinDistance explicitly ignores Triangle-Line. Saved actual curves had point-proxy cover bound1.282665mm and optimistic consecutive-line bound0.094917mm; largest wall triangle inradius0.716737mm. A general no-missed-wall-contact certificate does not follow from radius equality or enabled models. These conservative bounds do NOT demonstrate actual penetration, and no parameters or thresholds were changed.','','First phase remains NOT_VERIFIED for required whole-body coverage; strict mesh self-intersection remains NOT_VERIFIED. The short ten-environment motion test is NOT an anti-penetration PASS.','','## Assets','','|Seed|Split|Result|Directory|','|---:|---|---|---|']
    for a in assets:lines.append('|%d|%s|%s|%s|'%(a['seed'],a['split'],a['status'],a['directory'] or '-'))
    lines+=['','All source data are retained under the independent pretrain_20261020_d085_vox03 root. Nothing overwrote old1.0 or0.85 assets. The production default cache was not published while the mandatory first-phase gate is unverified. Evaluation1101/1202 therefore remain not generated under the original release condition.','','The production --preflight command succeeded as a configuration check, but it does not validate asset loading; separate default inventory found0/12 available.','','## Reports and commands','','Cohort provenance:ten_cohort_generation.json. Per-seed Stage A:seed*_cohort_stage_a.json. Ten-process raw report:phase3_ten_parallel/report.json. Raw resource samples:phase3_ten_parallel/resource_samples.json.','','    python -B python/testing/mcr_sim_wall_acceptance/test_scripts/pretrain_generate_cohort.py','','    timeout --signal=INT --kill-after=20s 900s python -B -u python/testing/mcr_sim_wall_acceptance/test_scripts/pretrain_ten_parallel.py '+str(root),'','Source preservation: '+r['production_source_preservation']['status']+'; no rewards, actions, physics, LSTM-SAC, assets from earlier runs, or thresholds modified.']
    (root/'FINAL_REPORT.md').write_text('\n'.join(lines)+'\n');print('FINAL',r['overall_status'],'rate',rate,'peak_RSS_GiB',r['performance']['peak_simultaneous_worker_rss_gib'])
if __name__=='__main__':main(sys.argv[1])
